// =====================================================================
// CLAIMS CALENDAR
//
// These are the big one-off and recurring claims. Most are worth more than
// everything else in this system combined, and every one of them is lost
// purely to forgetting.
//
// Mirrors config/levers.yml -> claims
// Set `enabled: false` on anything that does not apply to you.
// Rates change each April — re-check the values after each Budget.
// =====================================================================

const CLAIMS = [
  {
    id: 'child_benefit',
    enabled: true,
    once: true,
    title: 'Register for Child Benefit — even if you have to pay it back',
    annual_value_gbp: 1350,
    minutes: 20,
    url: 'https://www.gov.uk/child-benefit/how-to-claim',
    detail:
      'Claim in the name of the LOWER-earning or non-earning parent. That awards '
    + 'National Insurance credits toward their State Pension. If the High Income '
    + 'Child Benefit Charge applies to your household, still register and tick '
    + '"do not pay me" — you keep the NI credits without the tax charge. '
    + 'Not registering at all is the single most expensive admin mistake new '
    + 'UK parents make; it can cost tens of thousands in lost State Pension.',
  },
  {
    id: 'tax_free_childcare_setup',
    enabled: true,
    once: true,
    title: 'Open a Tax-Free Childcare account — government adds 25%',
    annual_value_gbp: 2000,
    minutes: 30,
    url: 'https://www.gov.uk/apply-for-tax-free-childcare',
    detail:
      'For every £8 you pay in, the government adds £2, up to £500 per quarter '
    + 'per child. That is a guaranteed 25% return on money you are already '
    + 'spending on childcare. No investment matches it. '
    + 'Note: you cannot combine this with childcare vouchers from an employer — '
    + 'check which is better for you before switching.',
  },
  {
    id: 'tax_free_childcare_reconfirm',
    enabled: true,
    // Every 3 months, forever. Miss it and the top-ups silently stop.
    recurring_days: 88,
    title: 'Reconfirm your Tax-Free Childcare details (takes 5 minutes)',
    annual_value_gbp: 500,
    minutes: 5,
    url: 'https://www.gov.uk/sign-in-childcare-account',
    detail:
      'HMRC requires reconfirmation every 3 months. If you miss it, the account '
    + 'stops receiving top-ups and nobody tells you. This reminder fires a few '
    + 'days early on purpose.',
  },
  {
    id: 'marriage_allowance',
    enabled: true,
    once: true,
    title: 'Claim Marriage Allowance + backdate 4 years (~£1,000 lump sum)',
    annual_value_gbp: 252,
    minutes: 15,
    url: 'https://www.gov.uk/marriage-allowance',
    detail:
      'Applies if one of you earns under the Personal Allowance and the other is '
    + 'a basic-rate taxpayer. The lower earner transfers £1,260 of their unused '
    + 'allowance. Worth about £252/year AND backdatable four tax years, which is '
    + 'usually paid as a lump sum of roughly £1,000. '
    + 'Claim direct on gov.uk — never use a claims company, they take a huge cut '
    + 'of a form that takes fifteen minutes.',
  },
  {
    id: 'pension_match',
    enabled: true,
    once: true,
    title: 'Check you are contributing enough to get the full employer pension match',
    annual_value_gbp: 900,
    minutes: 10,
    url: null,
    detail:
      'If your employer matches up to (say) 6% and you contribute 3%, you are '
    + 'declining free money — it is a pay rise you have not accepted. '
    + 'Contributions are pre-tax, so raising your percentage costs your take-home '
    + 'far less than the headline figure suggests.',
  },
  {
    id: 'bank_switch_check',
    enabled: true,
    // Offers rotate constantly; check quarterly.
    recurring_days: 90,
    title: 'Check current bank switching offers (£100–£200 each, genuinely free)',
    annual_value_gbp: 175,
    minutes: 30,
    url: 'https://www.moneysavingexpert.com/banking/best-bank-accounts/',
    detail:
      'The Current Account Switch Service moves your direct debits for you and '
    + 'guarantees the switch. Several banks pay £100–£200 to take your account at '
    + 'any given time. Open a spare account to switch FROM so your salary account '
    + 'is never disrupted. This is repeatable — people do it several times a year.',
  },
  {
    id: 'regular_saver',
    enabled: true,
    recurring_days: 180,
    title: 'Check regular saver accounts (6–8%, far above normal savings)',
    annual_value_gbp: 120,
    minutes: 15,
    url: 'https://www.moneysavingexpert.com/savings/best-regular-savings-accounts/',
    detail:
      'Regular savers pay well above easy-access rates but cap monthly deposits '
    + '(often £200–£500). Usually restricted to existing current-account customers, '
    + 'so pair this with whichever bank you switched to.',
  },
  {
    id: 'insurance_shop_around',
    enabled: true,
    recurring_days: 365,
    title: 'Annual insurance sweep — never, ever auto-renew',
    annual_value_gbp: 400,
    minutes: 45,
    url: null,
    detail:
      'Car, home, and life insurers price loyalty as a penalty: the renewal quote '
    + 'is almost always worse than the new-customer price for the identical cover. '
    + 'Get comparison quotes about 3 weeks before renewal (that is when premiums '
    + 'tend to be cheapest), then either switch or phone and ask them to match it.',
  },
];

// ---------------------------------------------------------------------
// Decide what is due today.
// ---------------------------------------------------------------------
const today = new Date();
const epochDay = Math.floor(today.getTime() / 86400000);
const due = [];

for (const claim of CLAIMS) {
  if (!claim.enabled) continue;

  let dedupeKey;

  if (claim.once) {
    // Fires exactly once, ever. Dismissing it in the actions table is
    // what marks it complete.
    dedupeKey = `claim:${claim.id}`;
  } else if (claim.recurring_days) {
    // Bucket time into fixed windows so the same window can only ever
    // produce one action, no matter how many times this workflow runs.
    const window = Math.floor(epochDay / claim.recurring_days);
    dedupeKey = `claim:${claim.id}:w${window}`;
  } else {
    continue;
  }

  due.push({
    dedupe_key: dedupeKey,
    source: 'claims',
    title: claim.title,
    detail: claim.detail + (claim.url ? `\n\nDo it here: ${claim.url}` : ''),
    action_url: claim.url,
    annual_value_gbp: claim.annual_value_gbp,
    minutes_required: claim.minutes,
  });
}

return [{ json: { due, count: due.length } }];

const data = $input.first().json;

function esc(v) {
  if (v === null || v === undefined) return 'NULL';
  return "'" + String(v).replace(/'/g, "''") + "'";
}

// ON CONFLICT DO NOTHING is the entire anti-nag mechanism here. A one-off
// claim inserts once and never again; a recurring one inserts once per
// window. Dismissing an action does not delete it, so it stays suppressed.
const statements = (data.due || []).map(f =>
  `INSERT INTO money.actions
  (dedupe_key, source, title, detail, action_url, annual_value_gbp, minutes_required, status)
VALUES (${esc(f.dedupe_key)}, ${esc(f.source)}, ${esc(f.title)}, ${esc(f.detail)},
        ${esc(f.action_url)}, ${f.annual_value_gbp}, ${f.minutes_required}, 'open')
ON CONFLICT (dedupe_key) DO NOTHING;`
);

statements.push(`INSERT INTO money.sync_log (workflow, ok, rows_ingested, message)
VALUES ('04-claims-calendar', true, ${(data.due || []).length}, 'claims evaluated');`);

return [{ json: { sql: statements.join('\n') } }];
